using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;
using UnityEngine.TestTools;
namespace Wildfolk.Tests
{
    public sealed class EconomyFoundationPlayTests
    {
        private string root,previous;private AccountService account;private FakeCloud cloud;private EconomyService service;
        private sealed class Identity:IAccountIdentityProvider {public string PlayerId=>"economy-isolated-player";public bool Linked=>true;public Task Connect()=>Task.CompletedTask;public Task UseExisting()=>Connect();public void SignOut(bool clearSession=false){}}
        private sealed class FakeCloud:IAccountCloudTransport,IEconomyTransport
        {
            public bool Engineer,InvalidAck;public Action DuringProgress;public int Calls,ProgressCalls,Claims;public string LastOperation;public TaskCompletionSource<EconomyReply> Delayed;
            Task<AccountReply> IAccountCloudTransport.Call(string op,Dictionary<string,object> input){var p=AccountProgression.New();p.Find("engineer").Owned=Engineer;return Task.FromResult(new AccountReply{ok=true,profile=new CloudAccountProfile{Schema=1,PlayerId="economy-isolated-player",SupportId="LF-1234-5678-90AB-CDEF-1234",CreatedAt="2026-10-26T00:00:00Z",ProviderLinked=true,ClassProfile=CloudClassProfile.From(p),Entitlements=Array.Empty<AccountEntitlement>()}});}
            public Task<EconomyReply> Call(string op,Dictionary<string,object> input){Calls++;LastOperation=op;if(Delayed!=null)return Delayed.Task;if(op=="SubmitProgress"){ProgressCalls++;DuringProgress?.Invoke();}if(op=="UnlockEngineer")Engineer=true;if(op=="ClaimAll")Claims++;
                var snapshot=new EconomySnapshot{Schema=1,CatalogRevision=1,PlayerId="economy-isolated-player",EnvironmentId=BackendSettings.Current.Environment.Id,ServerTime="2026-10-26T00:00:00Z",NextReset="2026-10-27T00:00:00Z",Balance=Engineer?0:120,EngineerOwned=Engineer,EngineerCost=120,ReviveCost=8,total=58,Metrics=new[]{new EconomyDelta{Id="hostiles",Value=5}},Boards=new[]{new EconomyBoard{Id="newcomer",Count=0,Rewards=EconomyCatalog.Current.Newcomer,Available=true,State="active"},new EconomyBoard{Id="monthly",Period="2026-10",Count=0,Rewards=EconomyCatalog.Current.Monthly,Available=true,State="active"}}};return Task.FromResult(new EconomyReply{ok=true,snapshot=snapshot,acknowledged=!InvalidAck&&input.ContainsKey("last")?(int)input["last"]:0});}
        }
        [UnitySetUp]public IEnumerator Setup(){previous=UnityEditor.SessionState.GetString("Wildfolk.QA.Directory","");root=Path.Combine(Path.GetTempPath(),"LowfireEconomyPlay-"+Guid.NewGuid().ToString("N"));UnityEditor.SessionState.SetString("Wildfolk.QA.Directory",root);ClassProfiles.DevelopmentProviders(new LocalAccountProgressionStore(Path.Combine(root,"guest")));cloud=new FakeCloud();account=AccountService.InstallDevelopment(new Identity(),cloud);SceneFlow.Repository=SaveRepository.Default();yield return SceneManager.LoadSceneAsync(SceneFlow.HomeScene);yield return null;service=EconomyService.InstallDevelopment(account,cloud);var t=account.Connect();while(!t.IsCompleted)yield return null;}
        [UnityTearDown]public IEnumerator Cleanup(){EconomyService.ClearDevelopment();ClassProfiles.AttachCloud(null);SceneFlow.Repository=null;UnityEditor.SessionState.SetString("Wildfolk.QA.Directory",previous);if(Directory.Exists(root))Directory.Delete(root,true);yield return null;}
        [UnityTest]public IEnumerator CanonicalOfflineEventsBatchOnceAndCachedGemCannotBeSpent(){service.Record("fish",1,"actual-catch");service.Record("fish",1,"actual-catch");Assert.That(cloud.Calls,Is.Zero);var t=service.Sync();while(!t.IsCompleted)yield return null;Assert.That(cloud.ProgressCalls,Is.EqualTo(1));Assert.That(service.Snapshot.Balance,Is.EqualTo(120));Assert.That(service.Badge,Is.True);account.KeepLocal();Assert.That(service.CanSpend,Is.False);Assert.That(ReviveServices.Wallet.Available,Is.False);Assert.That(service.Snapshot.Balance,Is.EqualTo(120));t=service.Claim();while(!t.IsCompleted)yield return null;Assert.That(cloud.Claims,Is.Zero);}
        [UnityTest]public IEnumerator EngineerGrantComesFromServerProfileAndSurvivesEconomyRefresh(){var t=service.Sync();while(!t.IsCompleted)yield return null;var purchase=service.UnlockEngineer();while(!purchase.IsCompleted)yield return null;Assert.That(purchase.Result,Is.True);Assert.That(ClassProfiles.Local.Find("engineer").Owned,Is.True);Assert.That(service.Snapshot.Balance,Is.Zero);}
        [UnityTest]public IEnumerator AuthoredJournalControlsClaimAndSeparateBoardsHaveClearEmptyState(){var t=service.Sync();while(!t.IsCompleted)yield return null;var screen=UnityEngine.Object.FindFirstObjectByType<EconomyScreen>();screen.OpenAchievements();yield return null;Assert.That(screen.AchievementView.activeSelf,Is.True);Assert.That(screen.Categories.Length,Is.EqualTo(7));Assert.That(screen.ClaimAll.interactable,Is.True);screen.ClaimEverything();yield return null;Assert.That(cloud.Claims,Is.EqualTo(1));screen.Back();screen.OpenAttendance();yield return null;Assert.That(screen.Slots.Count(b=>b.gameObject.activeSelf),Is.EqualTo(7));screen.Board(1);Assert.That(screen.Slots.Count(b=>b.gameObject.activeSelf),Is.EqualTo(28));Assert.That(screen.SlotLabels[0].text,Does.Contain(L.Text("meta.stamp")));screen.Board(2);Assert.That(screen.Attend.interactable,Is.False);Assert.That(screen.BoardTitle.text,Is.EqualTo(L.Text("economy.no_event")));screen.Back();Assert.That(screen.Home.Menu.activeSelf,Is.True);var classes=UnityEngine.Object.FindFirstObjectByType<ClassLobbyScreen>();classes.Open();classes.SelectCard(5);Assert.That(classes.PremiumCurrency.text,Is.EqualTo("120"));Assert.That(classes.Currency.text,Is.EqualTo(ClassProfiles.GoldAvailable(classes.Rules).ToString()));Assert.That(classes.PurchaseButton.interactable,Is.True);classes.Back();}
        [UnityTest]public IEnumerator ADelayedOldAccountReplyCannotMaterializeAfterSignout(){cloud.Delayed=new TaskCompletionSource<EconomyReply>();var t=service.History();account.SignOut();cloud.Delayed.SetResult(new EconomyReply{ok=true});while(!t.IsCompleted)yield return null;Assert.That(t.Result.error,Is.EqualTo("account_changed"));Assert.That(service.CanSpend,Is.False);}
        [UnityTest]public IEnumerator DirtyClassMirrorKeepsAuthenticatedWalletOnlineButOfflineChoiceNeverReopensIt(){var t=service.Sync();while(!t.IsCompleted)yield return null;var profile=ClassProfiles.Local;profile.Find("survivor").XP=1;Assert.That(ClassProfiles.Store.Write(ClassProfiles.LocalId,profile),Is.True);Assert.That(account.Dirty,Is.True);Assert.That(service.Online,Is.True,"local ClassXP is pending sync, not loss of Authentication");account.KeepLocal();profile.Find("survivor").XP=2;ClassProfiles.Store.Write(ClassProfiles.LocalId,profile);Assert.That(service.Online,Is.False,"a later local write must not undo explicit offline choice");}
        [UnityTest]public IEnumerator DetailScrollReflowsAtPixelScaleAndLanguageChanges()
        {
            var sync=service.Sync();while(!sync.IsCompleted)yield return null;var screen=UnityEngine.Object.FindFirstObjectByType<EconomyScreen>();screen.OpenAchievements();screen.Category(1);yield return null;
            var canvas=screen.Detail.canvas.rootCanvas;var scaler=canvas.GetComponent<CanvasScaler>();var enabled=scaler.enabled;var scale=canvas.scaleFactor;var language=L.Language;var font=screen.Detail.fontSize;scaler.enabled=false;
            try{foreach(var next in new[]{1f,.6666667f,.375f,1f})foreach(var locale in new[]{"en","ko"}){canvas.scaleFactor=next;L.SetLanguage(locale);yield return null;Canvas.ForceUpdateCanvases();yield return null;
                Assert.That(screen.Detail.fontSize,Is.EqualTo(font),"readability is preserved");Assert.That(screen.Detail.rectTransform.rect.height+3,Is.GreaterThanOrEqualTo(screen.Detail.preferredHeight),locale+" at "+next);
                var scroll=screen.DetailScroll;scroll.verticalNormalizedPosition=0;Canvas.ForceUpdateCanvases();var content=new Vector3[4];var viewport=new Vector3[4];scroll.content.GetWorldCorners(content);scroll.viewport.GetWorldCorners(viewport);if(scroll.content.rect.height>scroll.viewport.rect.height+3)Assert.That(Mathf.Abs(content[0].y-viewport[0].y),Is.LessThan(3),"last tier reachable");
            }}finally{canvas.scaleFactor=scale;scaler.enabled=enabled;L.SetLanguage(language);screen.Back();}
        }
        [UnityTest]public IEnumerator InvalidAcknowledgementStopsAndRetainsTheOutbox(){cloud.InvalidAck=true;service.Record("fish",1,"one");var sync=service.Sync();while(!sync.IsCompleted)yield return null;Assert.That(cloud.ProgressCalls,Is.EqualTo(1));Assert.That(service.LastError,Is.EqualTo("invalid_progress_ack"));Assert.That(service.PendingProgress,Is.True);cloud.InvalidAck=false;sync=service.Sync();while(!sync.IsCompleted)yield return null;Assert.That(cloud.ProgressCalls,Is.EqualTo(2));Assert.That(service.PendingProgress,Is.False);}
        [UnityTest]public IEnumerator ProgressCreatedDuringRequestWaitsForTheNextFlush(){service.Record("fish",1,"before");cloud.DuringProgress=()=>{cloud.DuringProgress=null;service.Record("fish",1,"during");};var sync=service.Sync();while(!sync.IsCompleted)yield return null;Assert.That(cloud.ProgressCalls,Is.EqualTo(1));Assert.That(service.PendingProgress,Is.True);sync=service.Sync();while(!sync.IsCompleted)yield return null;Assert.That(cloud.ProgressCalls,Is.EqualTo(2));Assert.That(service.PendingProgress,Is.False);}
    }
}
